    public static String getRandomNickName(){
        return NICKNAME_ARRAY[RANDOM.nextInt(NICKNAME_ARRAY.length)];
    }

    public static List<String> getRandomNickNames(int i){
        return RANDOM.ints(i, 0,NICKNAME_ARRAY.length).mapToObj(index -> NICKNAME_ARRAY[index]).collect(Collectors.toList());
    }

    public static String getRandomAvatarUrl(){
        return AVATAR_ARRAY[RANDOM.nextInt(AVATAR_ARRAY.length)];
    }

    public static List<String> getRandomAvatarUrls(int i){
        return RANDOM.ints(i,0,AVATAR_ARRAY.length).mapToObj(index->AVATAR_ARRAY[index]).collect(Collectors.toList());
    }

